ui &lt;- fluidPage(
  textOutput("text"),
  verbatimTextOutput("code")
)

server &lt;- function(input, output, session) {
  output$text &lt;- renderText("Hello Friend!")
  output$code &lt;- renderPrint(summary(1:10))
}

